#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Run all four device_demo tests in sequence."""

import subprocess
import sys
from pathlib import Path

TESTS = (
    "test_get_sensors.py",
    "test_get_hands.py",
    "test_get_robot_model.py",
    "test_get_cameras.py",
)


def main() -> int:
    here = Path(__file__).resolve().parent
    args = sys.argv[1:]
    failed = []
    for name in TESTS:
        script = here / name
        print(f"\n>>> Running {name} {' '.join(args)}\n")
        rc = subprocess.call([sys.executable, str(script), *args], cwd=str(here))
        if rc != 0:
            failed.append(name)
    if failed:
        print("\nFailed:", ", ".join(failed))
        return 1
    print("\nAll device_demo tests passed.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
